-- Jasa Marga toll tariffs from the reference file, generated by
-- cmd/import-toll -reference. Source: TMS/NEW/MICROSERVICES/docs/tarif_tol_jasamarga_2026-10-27.csv
--
-- Replaces every 'jasamarga' row with the file's figures, so the source holds
-- exactly what the reference says. Other sources are untouched. A pair whose
-- gate has no position joins to nothing and inserts no row. Cells that failed
-- a check load as verdict 'review' and are never priced.
BEGIN;


DELETE FROM toll_tariffs WHERE source = 'jasamarga';

INSERT INTO toll_tariffs (kind, entry_gate, exit_gate, golongan, amount_rp, source, source_ref, verdict, issues)
SELECT 'closed', eg.id, xg.id, v.g, v.amount, 'jasamarga', 'TMS/NEW/MICROSERVICES/docs/tarif_tol_jasamarga_2026-10-27.csv', 'usable', NULL
FROM toll_gates eg, toll_gates xg, (VALUES (1, 32000), (2, 48000), (3, 48000), (4, 64000), (5, 64000)) AS v(g, amount)
WHERE eg.name_norm = 'air madidi' AND xg.name_norm = 'bitung';
